visuals.shaderSource:
vec4 paintVisual(vec2 uv, CreatorFrame f) {
vec2 p = uv - 0.5;
p.x *= f.size.x / max(f.size.y, 1.0);
float t = f.time * f.speed * 0.32;
float seed = mod(f.seedLow + f.seedHigh, 10000.0) * 0.001;
vec3 c = f.color0.rgb * (0.7 + 0.3 * uv.y);
for (int i = 0; i < 4; i++) {
  float k = float(i);
  float center = 0.14 * sin(p.x * (2.0 + k * 0.32) + t + seed + k)
               + 0.08 * cos(p.x * 5.0 * f.detail - t * 0.6 + k)
               + (k - 1.5) * 0.105;
  float d = abs(p.y - center);
  float width = 0.014 + 0.013 * f.bass;
  float core = exp(-d * d / (width * width));
  float halo = exp(-d * 12.0) * 0.13 * f.glow;
  vec3 ink = mix(f.color1.rgb, f.color2.rgb, k / 3.0);
  ink = mix(ink, f.color3.rgb, 0.15 * (0.5 + 0.5 * sin(t + p.x * 2.0 + k)));
  c += ink * (core * 0.30 + halo) * f.intensity * (0.75 + 0.3 * f.energy + 0.15 * f.pulse);
}
float vignette = clamp(1.0 - dot(p, p) * 0.65, 0.25, 1.0);
return vec4(c * vignette, 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
 public:
  void reset(uint32_t) override {}
  void update(const Frame&) override {}
  void render(const Frame& f, Canvas& c) const override {
    c.material("chrome",{0,0,f.width,f.height},{float(f.time)*f.speed,f.music.bass});
    c.saveLayer(.32f,Blend::screen);
    Paint p;p.color={.7f,.83f,1,.65f};p.strokeWidth=.8f;
    for(int i=0;i<4;i++) {
      float x=f.width*(.16f+i*.23f);
      Path path;path.moveTo(x,0).cubicTo(x+35,f.height*.28f,x-40,f.height*.75f,x,f.height);
      c.path(path,p);
    }
    c.restore();
  }
};

shaderSources.chrome:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform float uTime;
uniform float uBass;
out vec4 fragColor;
float field(vec2 p) {
  float sum=0.;
  for(int i=0;i<7;i++) {
    float k=float(i);
    vec2 center=vec2(sin(uTime*.31+k*2.4),cos(uTime*.23+k*1.7))*.47;
    vec2 d=p-center;
    sum+=(.026+.006*sin(k+uTime*.2))/(dot(d,d)+.013);
  }
  return sum;
}
void main() {
  vec2 p=(FlutterFragCoord().xy/uSize-.5)*vec2(uSize.x/uSize.y,1.)*2.;
  float v=field(p),e=.004;
  vec2 g=vec2(field(p+vec2(e,0))-field(p-vec2(e,0)),field(p+vec2(0,e))-field(p-vec2(0,e)));
  vec3 n=normalize(vec3(-g*12.,.45));
  float rim=pow(1.-max(n.z,0.),2.);
  float stripe=.5+.5*sin(n.x*8.+n.y*4.+uTime*.09);
  vec3 metal=mix(vec3(.025,.04,.075),vec3(.77,.86,.94),smoothstep(.35,.7,stripe));
  metal+=pow(max(dot(n,normalize(vec3(-.5,-.6,1.))),0.),55.)*1.8;
  metal+=rim*vec3(.18,.35,.5);
  metal+=vec3(.24,.07,.3)*pow(max(n.y,0.),4.);
  float shape=smoothstep(.86-uBass*.06,.91-uBass*.06,v);
  vec3 bg=vec3(.018,.022,.038)+.02*exp(-dot(p,p));
  fragColor=vec4(mix(bg,metal,shape),1.);
}

visuals.shaderSource:
vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.0;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.5;

  float horizonY = -0.05;
  vec3 col = vec3(0.0);

  // Background deep sky gradient
  vec3 skyTop = vec3(0.02, 0.02, 0.08);
  vec3 skyHorizon = vec3(0.35, 0.05, 0.35);
  float skyGradient = smoothstep(horizonY, 1.2, p.y);
  col = mix(skyHorizon, skyTop, skyGradient);

  // Retro horizon glowing synth sun
  vec2 sunPos = vec2(0.0, horizonY + 0.32);
  float sunDist = length(p - sunPos);
  float sunRadius = 0.38 + 0.05 * bass;
  if (p.y > horizonY) {
    if (sunDist < sunRadius) {
      // Horizontal laser stripes cut through the sun
      float sunStripe = sin(p.y * 36.0);
      float stripeMask = smoothstep(0.2, 0.4, sunStripe);
      if (p.y < sunPos.y) {
        stripeMask = mix(1.0, stripeMask, smoothstep(sunPos.y - sunRadius, sunPos.y, p.y));
      } else {
        stripeMask = 1.0;
      }
      vec3 sunTopCol = vec3(1.0, 0.9, 0.2);
      vec3 sunBotCol = vec3(1.0, 0.15, 0.55);
      float sunY = (p.y - (sunPos.y - sunRadius)) / (sunRadius * 2.0);
      vec3 sunColor = mix(sunBotCol, sunTopCol, sunY);
      col = mix(col, sunColor, stripeMask);
    }
  }

  // Soft atmospheric sun corona glow
  float sunGlow = (0.04 + 0.06 * bass) / (sunDist * sunDist * 10.0 + 0.1);
  col += vec3(1.0, 0.25, 0.6) * sunGlow;

  // Infinite Perspective Cyber Grid (below horizon)
  if (p.y < horizonY) {
    // 3D ray projection onto the ground plane
    float py = horizonY - p.y;
    float depth = 1.0 / (py + 0.03);

    // Ground plane coordinates (x: sideways, z: forward depth)
    float worldX = p.x * depth * 0.85;
    float worldZ = depth * 1.5 + t * (2.5 + 2.5 * energy);

    // Topographical terrain elevation modulated by sound waves
    float mountainFreq = worldX * 0.35;
    float mountainH = sin(mountainFreq) * cos(worldZ * 0.15) * (0.8 + 0.5 * flow);
    // Shockwave ripple surging from the beat
    float ripple = sin(worldZ * 0.8 - t * 4.5) * (0.3 + 0.8 * bass);
    worldX += mountainH * 0.2;

    // Grid lines with antialiased inverse-distance glow
    float gridX = abs(fract(worldX) - 0.5) * 2.0;
    float gridZ = abs(fract(worldZ * 0.4) - 0.5) * 2.0;

    float lineX = 1.0 - smoothstep(0.0, 0.08 * (1.0 + depth * 0.05), gridX);
    float lineZ = 1.0 - smoothstep(0.0, 0.08 * (1.0 + depth * 0.05), gridZ);

    float gridLines = max(lineX, lineZ);
    // Sparkle points at grid vertices
    float vertices = pow(lineX * lineZ, 0.5) * (1.0 + 3.0 * spark);

    // Grid color ramp: Neon cyan near, hot magenta towards the horizon
    float fog = smoothstep(22.0, 2.0, depth);
    vec3 nearColor = vec3(0.15, 0.95, 1.0);
    vec3 farColor = vec3(1.0, 0.15, 0.75);
    vec3 gridColor = mix(farColor, nearColor, fog);

    vec3 groundSurface = gridColor * (gridLines * 1.2 + vertices * 2.0);
    // Dark metallic reflective ground under the grid lines
    vec3 groundBase = vec3(0.015, 0.01, 0.03) + sunGlow * vec3(0.2, 0.05, 0.15);

    vec3 finalGround = groundBase + groundSurface;
    col = mix(skyHorizon, finalGround, fog);
  }

  // Horizon laser separator line
  float horizonLine = exp(-abs(p.y - horizonY) * 65.0) * (0.6 + 0.8 * bass);
  col += vec3(0.3, 0.9, 1.0) * horizonLine;

  // Soft tone mapping and subtle vignette
  col = col / (col + vec3(0.85));
  float vignette = 1.0 - smoothstep(0.6, 1.5, length(p));
  col *= vignette;

  return vec4(clamp(col * f.intensity * f.glow, 0.0, 1.0), 1.0);
}

vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float crystalFacet(vec2 p, float size, float t, float bass) {
  vec2 q = abs(p);
  // Octahedral and dodecahedral folding planes
  float d1 = dot(q, normalize(vec2(1.0, 1.0))) - size;
  float d2 = dot(q, normalize(vec2(1.732, 1.0))) - size;
  float d3 = dot(q, normalize(vec2(1.0, 1.732))) - size;
  float d4 = max(q.x, q.y) - size * 0.92;
  return max(max(d1, d2), max(d3, d4));
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.42;

  vec3 col = vec3(0.0);
  float crystalBaseSize = 0.52 + 0.08 * bass;

  // 3-channel Chromatic Dispersion (Abbe number split)
  for (int ch = 0; ch < 3; ch++) {
    float dispersion = float(ch - 1) * (0.016 + 0.035 * spark);
    vec2 cp = p * (1.0 + dispersion);

    // Slowly rotating crystal body
    vec2 rotP = rotate2D(cp, t * 0.35 + bass * 0.25);

    // External crystal facets
    float dExt = crystalFacet(rotP, crystalBaseSize, t, bass);
    float edgeGlow = (0.018 + 0.025 * spark) / (abs(dExt) * 18.0 + 0.008);

    // Internal refracted layers / nested smaller crystal shells
    vec2 innerP1 = rotate2D(rotP * 1.55, -t * 0.55 + float(ch) * 0.2);
    float dInt1 = crystalFacet(innerP1, crystalBaseSize * 0.85, t, bass);
    float innerGlow1 = (0.012 + 0.02 * bass) / (abs(dInt1) * 22.0 + 0.012);

    vec2 innerP2 = rotate2D(rotP * 2.4, t * 0.75 + float(ch) * 0.4);
    float dInt2 = crystalFacet(innerP2, crystalBaseSize * 0.7, t, bass);
    float innerGlow2 = (0.008 + 0.015 * energy) / (abs(dInt2) * 28.0 + 0.015);

    // Caustic light rays radiating through the crystal faces
    float angle = atan(rotP.y / (rotP.x + 0.00001)) + (rotP.x < 0.0 ? 3.14159 : 0.0);
    float causticRays = pow(abs(cos(angle * 6.0 + t * 0.8)), 8.0) * (0.3 + 0.7 * bass);
    float rayFalloff = exp(-length(cp) * 2.2);
    float caustics = causticRays * rayFalloff;

    // Center radiant hyper-core
    float core = (0.08 + 0.32 * bass) / (length(cp) * length(cp) * 16.0 + 0.12);

    // Rainbow spectral palette
    vec3 palColor;
    if (ch == 0) {
      palColor = vec3(1.0, 0.15, 0.45); // Ruby / Magenta
    } else if (ch == 1) {
      palColor = vec3(0.15, 1.0, 0.65); // Emerald / Cyan
    } else {
      palColor = vec3(0.25, 0.55, 1.0); // Sapphire / Violet
    }

    float channelTotal = (edgeGlow * 0.45 + innerGlow1 * 0.35 + innerGlow2 * 0.25 + caustics * 0.5 + core * 0.7);

    col += palColor * channelTotal;
  }

  // Specular facet glints (sharp diamond flare)
  vec2 flareP = rotate2D(p, t * 0.35);
  float starX = exp(-abs(flareP.x) * 45.0) * exp(-abs(flareP.y) * 4.0);
  float starY = exp(-abs(flareP.y) * 45.0) * exp(-abs(flareP.x) * 4.0);
  float diamondFlare = (starX + starY) * (0.2 + 1.8 * spark);
  col += vec3(1.0, 0.98, 0.92) * diamondFlare;

  // Background velvet depth and cinematic vignette
  vec3 bg = vec3(0.012, 0.015, 0.03) * (1.0 - 0.4 * length(p));
  col = mix(bg, col, smoothstep(0.0, 0.15, length(col)));

  // Soft tone mapping
  col = col / (col + vec3(0.88));
  float vignette = 1.0 - smoothstep(0.45, 1.45, length(p));
  col *= vignette;

  return vec4(clamp(col * f.intensity * f.glow, 0.0, 1.0), 1.0);
}

vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float getAngle(vec2 p) {
  float r = length(p);
  if (r < 0.00001) { return 0.0; }
  float a = asin(clamp(p.y / r, -1.0, 1.0));
  if (p.x < 0.0) {
    a = 3.14159265 - a;
  }
  if (a < 0.0) {
    a = a + 6.2831853;
  }
  return a;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float r = length(p);
  float a = getAngle(p);

  float beat = clamp(f.pulse, 0.0, 1.0);
  float bass = clamp(f.bass, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);
  float t = f.time * 0.42 * f.speed;

  // Background deep sacred cosmic aura
  vec3 bgCol = mix(vec3(0.02, 0.008, 0.06), vec3(0.06, 0.015, 0.14), r * 0.8);
  bgCol = bgCol + vec3(0.1, 0.02, 0.18) * sin(r * 4.0 - t * 1.5) * 0.3;

  vec3 col = bgCol;

  // Fibonacci Petal Ring 1 (Inner 5 petals)
  float a1 = a + t * 0.6;
  float pet1 = cos(5.0 * a1);
  float r1 = 0.18 + 0.08 * pet1 + bass * 0.06;
  float d1 = abs(r - r1);
  float edge1 = 0.012 / (d1 + 0.012);
  vec3 col1 = mix(vec3(1.0, 0.85, 0.2), vec3(1.0, 0.25, 0.6), 0.5 + 0.5 * pet1);
  col = col + col1 * edge1 * 0.7;

  // Fibonacci Petal Ring 2 (Middle 8 petals, counter-rotating)
  float a2 = a - t * 0.4;
  float pet2 = cos(8.0 * a2);
  float r2 = 0.35 + 0.12 * pet2 + beat * 0.08;
  float d2 = abs(r - r2);
  float edge2 = 0.015 / (d2 + 0.018);
  vec3 col2 = mix(vec3(0.2, 0.85, 1.0), vec3(0.9, 0.1, 0.7), 0.5 + 0.5 * pet2);
  col = col + col2 * edge2 * 0.65;

  // Fibonacci Petal Ring 3 (Outer 13 petals)
  float a3 = a + t * 0.25;
  float pet3 = cos(13.0 * a3);
  float r3 = 0.58 + 0.15 * pet3 + bass * 0.1;
  float d3 = abs(r - r3);
  float edge3 = 0.018 / (d3 + 0.022);
  vec3 col3 = mix(vec3(0.95, 0.3, 0.8), vec3(1.0, 0.7, 0.2), 0.5 + 0.5 * pet3);
  col = col + col3 * edge3 * 0.6;

  // Fibonacci Petal Ring 4 (Ethereal 21 filaments)
  float a4 = a - t * 0.15;
  float pet4 = cos(21.0 * a4);
  float r4 = 0.82 + 0.14 * pet4 + beat * 0.06;
  float d4 = abs(r - r4);
  float edge4 = 0.012 / (d4 + 0.025);
  vec3 col4 = mix(vec3(0.4, 0.3, 1.0), vec3(0.2, 0.95, 0.8), 0.5 + 0.5 * pet4);
  col = col + col4 * edge4 * (0.4 + 0.3 * spark);

  // Sacred golden spiral rays
  float spiral1 = sin(log(r + 0.02) * 5.0 - a * 3.0 + t * 1.2);
  float spiral2 = sin(log(r + 0.02) * 5.0 + a * 3.0 - t * 1.2);
  float spiralGrid = smoothstep(0.85, 0.98, spiral1) + smoothstep(0.85, 0.98, spiral2);
  col = col + vec3(1.0, 0.8, 0.3) * spiralGrid * 0.35 * exp(-r * 1.8);

  // Radiant Golden Core / Lotus Stamen
  float coreDist = r;
  float coreGlow = 0.04 / (coreDist * coreDist * 6.0 + 0.04);
  float corePulse = 1.0 + 0.4 * sin(t * 4.0) + bass * 0.8;
  vec3 coreColor = mix(vec3(1.0, 0.95, 0.5), vec3(1.0, 0.4, 0.1), clamp(r * 5.0, 0.0, 1.0));
  col = col + coreColor * coreGlow * corePulse * 1.2;

  // Stardust / Pollen particles swirling around the flower
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float pAngle = fi * 1.047 + t * (0.8 + 0.2 * fi);
    float pRad = 0.25 + 0.15 * sin(fi * 2.1 + t * 1.5) + bass * 0.1;
    vec2 pPos = vec2(cos(pAngle), sin(pAngle)) * pRad;
    float pDist = length(p - pPos);
    float pGlow = 0.003 / (pDist * pDist * 25.0 + 0.003);
    col = col + vec3(1.0, 0.9, 0.4) * pGlow * (0.8 + 0.8 * spark);
  }

  // Soft tone mapping and cinematic vignette
  col = col / (col + vec3(0.85));
  float vig = 1.0 - smoothstep(0.5, 1.5, r);
  col = col * vig * f.intensity * f.glow;

  return vec4(clamp(col, 0.0, 1.0), 1.0);
}

vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

float getAngle(vec2 p) {
  float r = length(p);
  if (r < 0.00001) { return 0.0; }
  float a = asin(clamp(p.y / r, -1.0, 1.0));
  if (p.x < 0.0) {
    a = 3.14159265 - a;
  }
  if (a < 0.0) {
    a = a + 6.2831853;
  }
  return a;
}

// Multi-octave convective solar plasma noise
float solarNoise(vec2 p, float t) {
  float n = 0.0;
  n = n + sin(p.x * 6.0 + t * 1.2) * cos(p.y * 6.0 - t * 0.9);
  n = n + sin(p.x * 14.0 - t * 1.8 + p.y * 5.0) * 0.5;
  n = n + cos(p.y * 24.0 + t * 3.1 - p.x * 10.0) * 0.25;
  n = n + sin((p.x + p.y) * 36.0 + t * 4.5) * 0.12;
  return n * 0.53;
}

// Blackbody thermal incandescent ramp (0=dark vacuum, 1=blinding white)
vec3 blackbody(float heat) {
  vec3 col = vec3(0.0);
  col = mix(col, vec3(0.65, 0.03, 0.0), smoothstep(0.0, 0.32, heat));
  col = mix(col, vec3(1.0, 0.32, 0.02), smoothstep(0.24, 0.62, heat));
  col = mix(col, vec3(1.0, 0.88, 0.18), smoothstep(0.52, 0.82, heat));
  col = mix(col, vec3(1.0, 1.0, 0.98), smoothstep(0.78, 1.05, heat));
  return col;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float t = f.time * 0.55 * f.speed;
  float bass = clamp(f.bass, 0.0, 1.0);
  float beat = clamp(f.pulse, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);

  float r = length(p);
  float a = getAngle(p);

  // Stellar core radius with bass pulsation
  float coreRadius = 0.34 + bass * 0.09 + beat * 0.04;

  // Background deep space with hot ambient nebula dust
  vec3 col = vec3(0.015, 0.003, 0.008) + vec3(0.14, 0.018, 0.0) * exp(-r * 1.6);

  // Shockwave blast rings propagating outward
  float wavePhase = mod(r * 2.8 - t * 2.0, 2.0);
  float shock = exp(-abs(wavePhase - 1.0) * 14.0) * exp(-r * 0.9);
  col = col + vec3(1.0, 0.45, 0.08) * shock * (0.6 + 0.9 * bass);

  // Solar Prominences / coronal mass ejections (flares radiating outward)
  float flares = 0.0;
  for (int i = 0; i < 6; i++) {
    float fi = float(i);
    float flareAngle = fi * 1.047 + sin(t * 0.4 + fi * 1.2) * 0.35;
    float da = abs(mod(a - flareAngle + 3.14159, 6.28318) - 3.14159);
    float flareDist = abs(r - (coreRadius + 0.18 + 0.16 * sin(t * 2.2 + fi * 2.0) + bass * 0.18));
    float flareIntensity = exp(-da * 8.5) * exp(-flareDist * 9.0);
    flares = flares + flareIntensity;
  }
  col = col + vec3(1.0, 0.38, 0.06) * flares * 2.0;

  // Ethereal coronal streamers (solar wind filaments)
  float rays = sin(a * 16.0 + t * 2.2 + sin(r * 6.0 - t * 3.5)) * 0.5 + 0.5;
  rays = rays * smoothstep(coreRadius * 0.8, 1.3, r) * exp(-r * 2.0);
  col = col + vec3(1.0, 0.55, 0.12) * rays * (0.8 + 0.8 * beat);

  // Magnetic coronal loops (toroidal magnetic flux arches)
  for (int m = 0; m < 5; m++) {
    float fm = float(m);
    vec2 loopCenter = vec2(cos(fm * 1.256 + t * 0.35), sin(fm * 1.256 + t * 0.35)) * (coreRadius * 0.92);
    float dLoop = length(p - loopCenter);
    float loopRadius = 0.13 + 0.05 * sin(t * 1.6 + fm * 1.8);
    float loopRing = abs(dLoop - loopRadius);
    float loopGlow = 0.0035 / (loopRing * loopRing * 22.0 + 0.004);
    col = col + vec3(1.0, 0.75, 0.25) * loopGlow * (0.7 + 0.6 * spark);
  }

  // Solar photosphere surface with boiling convective granulation
  if (r < coreRadius * 1.25) {
    vec2 surfCoord = rotate2D(p, t * 0.18);
    float granulation = solarNoise(surfCoord * 5.0, t * 1.5);

    // Radial darkening towards the limb, searing nuclear interior
    float radialFactor = clamp((coreRadius - r) / coreRadius, 0.0, 1.0);
    float heat = radialFactor * 0.92 + granulation * 0.32 + bass * 0.35;
    vec3 sunSurface = blackbody(clamp(heat, 0.0, 1.25));

    // Crisp limb transition with solar atmosphere rim
    float diskAlpha = smoothstep(coreRadius + 0.02, coreRadius - 0.02, r);
    col = mix(col, sunSurface, diskAlpha);
  }

  // Radiant nuclear core glow
  float coreGlow = 0.06 / (r * r * 8.5 + 0.06);
  col = col + vec3(1.0, 0.92, 0.75) * coreGlow * (0.9 + 1.1 * bass);

  // High-energy relativistic plasma sparks
  for (int s = 0; s < 8; s++) {
    float fs = float(s);
    float spAngle = fs * 0.785 + t * (1.3 + 0.25 * fs);
    float spRad = coreRadius + 0.10 + 0.28 * fract(sin(fs * 43.12) * 532.1 + t * 0.45);
    vec2 spPos = vec2(cos(spAngle), sin(spAngle)) * spRad;
    float spDist = length(p - spPos);
    float sparkGlow = 0.002 / (spDist * spDist * 32.0 + 0.002);
    col = col + vec3(1.0, 0.9, 0.4) * sparkGlow * (1.0 + 1.3 * spark);
  }

  // Soft tone mapping and subtle vignette
  col = col / (col + vec3(0.82));
  float vig = 1.0 - smoothstep(0.5, 1.5, r);
  col = col * vig * f.intensity * f.glow;

  return vec4(clamp(col, 0.0, 1.0), 1.0);
}

