float liquidField(vec2 p, float t, float bass, float spark, float flow) {
  float r = length(p);
  // Concentric liquid ripples expanding from center
  float ripple = sin(r * (14.0 + 3.0 * flow) - t * 3.8) * (0.035 + 0.055 * bass);

  // Cross-interfering droplet orbits
  vec2 c1 = vec2(sin(t * 0.7) * 0.42, cos(t * 0.8) * 0.35);
  vec2 c2 = vec2(cos(t * 0.9 + 1.8) * 0.38, sin(t * 0.6) * 0.42);
  float wave1 = sin(length(p - c1) * 16.0 - t * 4.2) * (0.025 + 0.035 * bass);
  float wave2 = sin(length(p - c2) * 18.0 - t * 3.6) * (0.020 + 0.030 * spark);

  // High-frequency surface sizzle from spark / hi-hats
  float sizzle = sin(p.x * 32.0 + t * 4.5) * cos(p.y * 32.0 + t * 4.0) * (0.006 + 0.018 * spark);

  // Base organic dome
  float dome = exp(-r * r * 2.2) * 0.16;

  return dome + ripple + wave1 + wave2 + sizzle;
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.1;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.48;

  // Surface Normal via finite differences
  float eps = 0.0035;
  float hC = liquidField(p, t, bass, spark, flow);
  float hR = liquidField(p + vec2(eps, 0.0), t, bass, spark, flow);
  float hU = liquidField(p + vec2(0.0, eps), t, bass, spark, flow);

  vec3 normal = normalize(vec3((hC - hR) / eps, (hC - hU) / eps, 0.32));

  // Environmental reflection vector
  vec3 view = normalize(vec3(p * 0.22, 1.0));
  vec3 ref = reflect(-view, normal);

  // Studio lighting environment ramp (chrome horizon, deep velvet zenith)
  float horizon = smoothstep(-0.25, 0.25, ref.y);
  float stripe = sin(ref.y * 12.0 + ref.x * 6.0 + t * 0.25);
  float studioStripe = smoothstep(0.35, 0.75, stripe);

  vec3 deepMetal = vec3(0.02, 0.035, 0.07);
  vec3 silver = vec3(0.85, 0.90, 0.98);
  vec3 neonCyan = vec3(0.20, 0.85, 1.0);
  vec3 neonMagenta = vec3(0.95, 0.20, 0.65);

  vec3 chrome = mix(deepMetal, silver, horizon * 0.8 + studioStripe * 0.25);

  // Directional specular glints
  vec3 lightDir1 = normalize(vec3(-0.45, 0.7, 0.6));
  float spec1 = pow(max(dot(ref, lightDir1), 0.0), 36.0) * (1.6 + 2.4 * spark);
  vec3 lightDir2 = normalize(vec3(0.55, -0.5, 0.55));
  float spec2 = pow(max(dot(ref, lightDir2), 0.0), 22.0) * (0.8 + 1.4 * bass);

  // Fresnel rim glow with subtle chromatic sheen
  float fresnel = pow(1.0 - max(dot(normal, view), 0.0), 2.6);
  vec3 rimColor = mix(neonCyan, neonMagenta, 0.5 + 0.5 * sin(t * 0.35 + p.y * 2.2));

  // Combine chrome surface
  vec3 surface = chrome + (spec1 + spec2) * vec3(1.0, 0.98, 0.93) + fresnel * rimColor * (0.65 + 0.85 * energy);

  // Smooth dropoff into deep velvet background
  float fluidAlpha = smoothstep(1.4, 0.85, length(p));
  vec3 bg = vec3(0.015, 0.02, 0.035) * (1.0 - 0.45 * length(p));
  vec3 finalColor = mix(bg, surface, fluidAlpha);

  return vec4(clamp(finalColor * f.intensity * f.glow, 0.0, 1.0), 1.0);
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
vec2 q = uv - 0.5;
vec2 p = q;
p.x *= max(f.size.x, 1.0) / max(f.size.y, 1.0);

float intensity = clamp(f.intensity, 0.0, 2.0);
float speed = clamp(f.speed, 0.0, 3.0);
float detail = clamp(f.detail, 0.0, 2.0);
float glow = clamp(f.glow, 0.0, 2.0);

float t = f.time * speed * 0.28;
float seed = mod(
f.seedLow * 0.0174533 + f.seedHigh * 0.0137137,
6.2831853
);

vec3 deepBlue = mix(
vec3(0.006, 0.022, 0.070),
f.color0.rgb * 0.35,
0.20
);
vec3 oceanBlue = mix(
vec3(0.018, 0.115, 0.290),
f.color1.rgb,
0.20
);
vec3 waveBlue = mix(
vec3(0.045, 0.310, 0.590),
f.color2.rgb,
0.22
);
vec3 lightBlue = mix(
vec3(0.240, 0.590, 0.820),
f.color3.rgb,
0.20
);

float depth = smoothstep(0.0, 1.0, uv.y);
vec3 c = mix(deepBlue, oceanBlue, 0.22 + 0.28 * depth);

vec2 lightPosition = vec2(
0.18 * sin(t * 0.23 + seed),
-0.12 + 0.06 * sin(t * 0.19 + seed * 0.71)
);
vec2 lightDistance = p - lightPosition;
float ambientLight = exp(-dot(lightDistance, lightDistance) * 1.65);
c += oceanBlue * ambientLight * 0.14;

float density = 1.70 + 0.60 * detail;
float amplitude = 0.075 + 0.055 * f.bass + 0.018 * f.energy;
float luminosity = 0.78 + 0.22 * f.energy;

for (int i = 0; i < 6; i++) {
float k = float(i);
float layer = k / 5.0;
float offset = seed + k * 0.92;

float primary = sin(
  p.x * density - t * (0.68 + 0.035 * k) + offset
);
float secondary = sin(
  p.x * (2.30 + 0.75 * detail)
  + t * 0.44
  + offset * 1.70
);

float center = (k - 2.5) * 0.17
  + p.x * 0.07
  + amplitude * primary
  + (0.032 + 0.014 * f.flow) * secondary;

float d = p.y - center;
float width = 0.067 + 0.006 * k + 0.020 * f.body;
float normalizedDistance = d / width;
float wave = exp(-normalizedDistance * normalizedDistance);

float crestDistance = (d + width * 0.30)
  / (0.024 + 0.009 * f.body);
float crest = exp(-crestDistance * crestDistance);

float faceLight = 1.0 - smoothstep(-width, width * 1.60, d);
vec3 ink = mix(oceanBlue, waveBlue, 0.28 + 0.60 * layer);
vec3 face = ink * (0.64 + 0.30 * faceLight);

float opacity = wave * (0.25 + 0.07 * f.energy) * intensity;
c = mix(c, face, opacity);

c += ink * wave
  * (0.065 + 0.035 * f.energy)
  * glow * intensity;

float reflection = 0.027 + 0.026 * f.spark + 0.008 * f.pulse;
c += lightBlue * crest * reflection
  * luminosity * glow * intensity;

}

float vignette = 1.0
- 0.26 * smoothstep(0.05, 0.50, dot(q, q));

return vec4(clamp(c * vignette, 0.0, 1.0), 1.0);
}

visuals.nativeSource:
class Visual final : public Scene {
  float smoothBass = 0.0f;
  float smoothEnergy = 0.0f;
  float smoothSpark = 0.0f;
  float plasmaTime = 0.0f;
  float ripplePhase = 0.0f;
  float colorPhase = 0.0f;

 public:
  void reset(uint32_t) override {
    smoothBass = 0.0f;
    smoothEnergy = 0.0f;
    smoothSpark = 0.0f;
    plasmaTime = 0.0f;
    ripplePhase = 0.0f;
    colorPhase = 0.0f;
  }

  void update(const Frame& f) override {
    float dt = float(f.delta);
    if (dt > 0.1f) dt = 0.1f;

    // Filtro exponencial asimétrico para respuesta musical orgánica sin tirones
    float targetBass = f.music.active ? f.music.bass : 0.0f;
    float targetEnergy = f.music.active ? f.music.energy : 0.0f;
    float targetSpark = f.music.active ? f.music.spark : 0.0f;

    float bassRate = targetBass > smoothBass ? 16.0f : 4.5f;
    smoothBass += (targetBass - smoothBass) * (1.0f - std::exp(-dt * bassRate));
    smoothEnergy += (targetEnergy - smoothEnergy) * (1.0f - std::exp(-dt * 5.0f));
    smoothSpark += (targetSpark - smoothSpark) * (1.0f - std::exp(-dt * 10.0f));

    // Integración continua: la música modula la velocidad de flujo, nunca resetea la fase
    float speedMod = (1.0f + smoothEnergy * 0.75f + smoothBass * 0.5f) * f.speed;
    plasmaTime += dt * speedMod * 0.85f;
    ripplePhase += dt * (1.2f + smoothBass * 2.8f);
    colorPhase += dt * (0.04f + smoothBass * 0.10f + smoothEnergy * 0.06f);
  }

  void render(const Frame& f, Canvas& c) const override {
    c.material("plasma", {0, 0, f.width, f.height},
               {plasmaTime, ripplePhase, colorPhase, smoothBass, smoothEnergy, smoothSpark});
  }
};

shaderSources.plasma:
#version 460 core
#include <flutter/runtime_effect.glsl>
uniform vec2 uSize;
uniform float uTime;
uniform float uRipple;
uniform float uColorPhase;
uniform float uBass;
uniform float uEnergy;
uniform float uSpark;
out vec4 fragColor;

vec3 plasmaColor(float x) {
  float s = fract(x) * 8.0;
  int i = int(floor(s));
  float f = fract(s);
  f = f * f * (3.0 - 2.0 * f);

  vec3 c0 = vec3(0.005, 0.040, 0.120);
  vec3 c1 = vec3(0.000, 0.380, 0.580);
  vec3 c2 = vec3(0.000, 0.880, 0.760);
  vec3 c3 = vec3(0.500, 1.000, 0.380);
  vec3 c4 = vec3(1.000, 0.860, 0.220);
  vec3 c5 = vec3(1.000, 0.320, 0.300);
  vec3 c6 = vec3(0.960, 0.120, 0.680);
  vec3 c7 = vec3(0.240, 0.030, 0.380);

  vec3 colA = c0;
  vec3 colB = c1;
  if (i == 1) { colA = c1; colB = c2; }
  else if (i == 2) { colA = c2; colB = c3; }
  else if (i == 3) { colA = c3; colB = c4; }
  else if (i == 4) { colA = c4; colB = c5; }
  else if (i == 5) { colA = c5; colB = c6; }
  else if (i == 6) { colA = c6; colB = c7; }
  else if (i == 7) { colA = c7; colB = c0; }

  return mix(colA, colB, f);
}

void main() {
  vec2 uv = FlutterFragCoord().xy / uSize;
  float aspect = uSize.x / uSize.y;
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 6.5;

  vec2 c1 = vec2(sin(uTime * 0.45), cos(uTime * 0.38)) * 1.5;
  vec2 c2 = vec2(cos(uTime * 0.33 + 1.8), sin(uTime * 0.52)) * 1.4;

  float d1 = length(p - c1);
  float d2 = length(p - c2);

  float w1 = sin(p.x * 1.8 + uTime * 1.1);
  float w2 = sin(p.y * 2.1 + uTime * 0.95);
  float w3 = sin((p.x + p.y) * 1.5 + uTime * 0.75);
  float w4 = sin(d1 * 2.8 - uRipple * 2.2);
  float w5 = sin(d2 * 2.4 - uRipple * 1.7);

  vec2 warp = vec2(w1 + w5 * 0.4, w2 + w4 * 0.4) * (0.45 + uBass * 0.25);
  float w6 = sin(length(p + warp) * 2.6 - uTime * 1.2);

  float v = (w1 + w2 + w3 + w4 + w5 * 0.8 + w6 * 1.1) / 5.7;

  float phase = v * 0.85 + uColorPhase;
  vec3 col = plasmaColor(phase);

  float crest = pow(max(0.0, sin(v * 3.14159 * 2.0)), 6.0);
  vec3 filamentColor = mix(vec3(0.4, 0.8, 1.0), vec3(1.0, 0.9, 0.5), smoothstep(0.0, 1.0, uBass));
  col += filamentColor * (crest * (0.35 + uBass * 0.45 + uSpark * 0.4));

  col = mix(col, col * col * 1.4, uEnergy * 0.25);

  float vig = 1.0 - smoothstep(0.55, 1.4, length(uv - 0.5) * 1.35);
  col *= vig;

  fragColor = vec4(col, 1.0);
}

visuals.shaderSource:
vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

vec3 paletteCos(float t, vec3 a, vec3 b, vec3 c, vec3 d) {
  return a + b * cos(6.28318 * (c * t + d));
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.42;
  vec3 col = vec3(0.0);

  // Split into 3 chromatic channels for subtle optical dispersion
  for (int ch = 0; ch < 3; ch++) {
    float dispersion = float(ch - 1) * (0.012 + 0.022 * spark);
    vec2 cp = p * (1.0 + dispersion);

    float r = length(cp);
    // Logarithmic tunnel coordinate moving into the screen
    float z = 1.0 / (r + 0.06);
    float tunnelDepth = z * 0.55 - t * (1.1 + 0.9 * energy);

    // Dynamic rotation modulated by sub-bass and flow
    vec2 q = rotate2D(cp, t * 0.25 + z * 0.12 + bass * 0.35);

    // Iterated Sacred Geometry / Kaleidoscope Folding
    float accum = 0.0;
    vec2 k = q * (1.8 + 0.4 * flow);
    for (int i = 0; i < 4; i++) {
      float fi = float(i);
      k = abs(k) - vec2(0.32 + 0.12 * sin(t * 0.6 + fi * 1.3), 0.22 + 0.08 * cos(t * 0.45));
      k = rotate2D(k, 0.785398 + 0.25 * bass + fi * 0.3);
      accum += 1.0 / (length(k) * 22.0 + 1.0);
    }

    // Glowing harmonic tunnel rings
    float ringPattern = abs(sin(tunnelDepth * 3.14159));
    float ringGlow = (0.025 + 0.035 * bass) / (ringPattern * ringPattern + 0.007);

    // Center singularity core radiance
    float core = (0.10 + 0.35 * bass) / (r * r * 18.0 + 0.12);

    // Color ramp: electric cyan, deep magenta, warm gold
    vec3 pal = paletteCos(
      tunnelDepth * 0.16 + float(ch) * 0.06 + t * 0.05,
      vec3(0.5, 0.5, 0.5),
      vec3(0.5, 0.5, 0.5),
      vec3(1.0, 1.0, 1.0),
      vec3(0.05, 0.33, 0.67)
    );

    float intensity = (accum * 0.42 + ringGlow * 0.48 + core * 0.6) * f.intensity * f.glow;

    if (ch == 0) col.r += intensity * pal.r;
    else if (ch == 1) col.g += intensity * pal.g;
    else if (ch == 2) col.b += intensity * pal.b;
  }

  // Soft tone mapping and subtle cinematic vignette
  col = col / (col + vec3(0.85));
  float vignette = 1.0 - smoothstep(0.45, 1.45, length(p));
  col *= vignette;

  return vec4(col, 1.0);
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  vec2 p = (uv - 0.5) * vec2(f.size.x / max(f.size.y, 1.0), 1.0);
  float radius = 0.27 + 0.015 * sin(f.time * f.speed) + 0.025 * f.bass;
  float distance = abs(length(p) - radius);
  float beam = exp(-distance * distance * 17000.0);
  float halo = exp(-distance * 24.0) * 0.25 * f.glow;
  float alpha = clamp((beam * 0.62 + halo) * f.intensity * (0.8 + 0.2 * f.pulse), 0.0, 1.0);
  vec3 ink = mix(f.color1.rgb, f.color2.rgb, 0.5 + 0.5 * sin(p.x * 7.0 + f.time * 0.2));
  return vec4(ink, alpha);
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
vec2 p = (uv - 0.5) * vec2(f.size.x / max(f.size.y, 1.0), 1.0);
float t = f.time * f.speed * 0.2;
vec3 c = f.color0.rgb;
for (int i = 0; i < 3; i++) {
  float k = float(i);
  vec2 center = 0.08 * vec2(cos(t + k * 2.1), sin(t * 0.7 + k * 2.1));
  float r = length(p - center);
  float ring = abs(r - (0.15 + k * 0.085));
  float beam = exp(-ring * ring * 18000.0) * 0.5;
  float halo = exp(-ring * 30.0) * 0.13 * f.glow;
  vec3 ink = mix(f.color1.rgb, f.color3.rgb, k * 0.5);
  c += ink * (beam + halo) * f.intensity;
}
return vec4(c, 1.0);
}

vec2 rotate2D(vec2 p, float a) {
  float c = cos(a);
  float s = sin(a);
  return vec2(p.x * c - p.y * s, p.x * s + p.y * c);
}

vec4 paintVisual(vec2 uv, CreatorFrame f) {
  float aspect = max(f.size.x, 1.0) / max(f.size.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;

  float bass = clamp(f.bass, 0.0, 1.0);
  float energy = clamp(f.energy, 0.0, 1.0);
  float spark = clamp(f.spark, 0.0, 1.0);
  float flow = clamp(f.flow, 0.0, 1.0);

  float t = f.time * f.speed * 0.38;

  // Multi-frequency fluid domain warping
  vec2 q = vec2(
    sin(p.x * 1.8 + t * 0.45 + bass * 0.2),
    cos(p.y * 1.8 + t * 0.38 + flow * 0.3)
  );

  vec2 r = vec2(
    sin(p.x * 2.8 + q.y * 2.4 + t * 0.52),
    cos(p.y * 2.8 + q.x * 2.4 + t * 0.44)
  );

  // Sheer silk ribbon folds
  vec2 warpedP = p + r * (0.35 + 0.15 * flow);
  warpedP = rotate2D(warpedP, t * 0.12 + bass * 0.2);

  float ribbon1 = sin(warpedP.y * 4.2 + warpedP.x * 2.1 + t * 1.2);
  float ribbon2 = cos(warpedP.y * 5.6 - warpedP.x * 2.8 - t * 0.95);
  float ribbon3 = sin(length(warpedP) * 5.0 - t * 1.6);

  float sheet1 = 1.0 / (abs(ribbon1) * 14.0 + 1.0);
  float sheet2 = 1.0 / (abs(ribbon2) * 16.0 + 1.0);
  float sheet3 = 1.0 / (abs(ribbon3) * 12.0 + 1.0);

  // Bioluminescent deep-ocean palette
  vec3 deepNavy = vec3(0.008, 0.024, 0.070);
  vec3 bioEmerald = vec3(0.08, 0.96, 0.60);
  vec3 bioCyan = vec3(0.15, 0.85, 1.0);
  vec3 bioViolet = vec3(0.62, 0.10, 0.95);
  vec3 warmSparkle = vec3(1.0, 0.95, 0.80);

  // Layered transmission & rim light
  vec3 col = deepNavy;
  col += bioCyan * sheet1 * (0.75 + 0.55 * bass);
  col += bioEmerald * sheet2 * (0.65 + 0.65 * energy);
  col += bioViolet * sheet3 * (0.55 + 0.45 * flow);

  // Bioluminescent micro-spores dancing on the crests
  float sporeGrid = sin(warpedP.x * 32.0 + t * 4.0) * cos(warpedP.y * 32.0 - t * 3.5);
  float spores = smoothstep(0.72, 0.98, sporeGrid) * (sheet1 + sheet2);
  col += warmSparkle * spores * (0.4 + 2.2 * spark);

  // Soft caustics / volumetric underwater rays
  float rays = sin(p.x * 6.0 + p.y * 3.0 + t * 0.8) * 0.5 + 0.5;
  col += bioCyan * rays * 0.12 * (1.0 + bass * 0.6);

  // Tone mapping and gentle vignette
  col = col / (col + vec3(0.9));
  float vignette = 1.0 - smoothstep(0.5, 1.45, length(p));
  col *= vignette;

  return vec4(clamp(col * f.intensity * f.glow, 0.0, 1.0), 1.0);
}

